def regexr_transform(column):
    return_list = []

    for value in column:
        # Standardize the representation of "private"
        if 'GOVERNMENT' in value or 'VOLUNTARY NON-PROFIT' in value:
            if re.search(r'[-_]private', value):
                value = re.sub(r'[-_]private', 'Private', value)
            elif re.search(r'[-_]priwate', value):
                value = re.sub(r'[-_]priwate', 'Private', value)
            elif re.search(r'[-_]privat', value):
                value = re.sub(r'[-_]privat', 'Private', value)
        # Standardize the representation of "church"
        if 'VOLUNTARY NON-PROFIT - CHURCH' in value:
            if re.search(r'[-_]church', value):
                value = re.sub(r'[-_]church', 'Church', value)

        return_list.append(value)

    # Count ZIP codes based on the diversity of hospital types and ownerships
    unique_hospitals = set([hospital.split()[0] for hospital in return_list])
    zip_count = len({hospital.split()[1] for hospital in return_list})

    return f'Hospital Types: {len(unique_hospitals)}, ZIP Codes: {zip_count}'
return value

